#include "sqlite3.h"
int consumer(sqlite3 *db) {
 sqlite3_stmt *s = 0;
 int rc = sqlite3_prepare_v2(db, "SELECT 47, NULL", -1, &s, 0);
 if (rc) return 1;
 rc = sqlite3_step(s);
 if (rc != SQLITE_ROW || sqlite3_column_int(s, 0) != 47 || sqlite3_column_type(s, 1) != SQLITE_NULL) { sqlite3_finalize(s); return 1; }
 return sqlite3_finalize(s);
}

#include "sqlite3.h"
int consumer(sqlite3 *);
int main(void) {
 sqlite3 *db = 0;
 int rc;
 if (sqlite3_open(":memory:", &db)) return 1;
 rc = consumer(db);
 return sqlite3_close(db) || rc;
}

#include "sqlite3ext.h"
SQLITE_EXTENSION_INIT1
static void answer(sqlite3_context *c, int argc, sqlite3_value **argv) {
 (void)argc; (void)argv; sqlite3_result_int(c, 47);
}
int extension(sqlite3 *db) {
 return sqlite3_create_function(db, "answer", 0, SQLITE_UTF8, 0, answer, 0, 0);
}

#include "sqlite3ext.h"
SQLITE_EXTENSION_INIT3
int extension(sqlite3 *);
int main(void) {
 sqlite3 *db = 0;
 sqlite3_stmt *s = 0;
 int rc;
 if (sqlite3_open(":memory:", &db)) return 1;
 if (extension(db)) return 2;
 if (sqlite3_prepare_v2(db, "SELECT answer()", -1, &s, 0)) return 3;
 rc = sqlite3_step(s) != SQLITE_ROW || sqlite3_column_int(s, 0) != 47;
 sqlite3_finalize(s);
 return sqlite3_close(db) || rc;
}
